      const continuation = resolveRideContinuationSetup({
        anchorLngLat,
        lastRide: continuationLastRideRef.current,
        sessionPrefs: getLastSessionPrefs(),
        currentProfile: profile,
        currentRouteDistanceMeters: routeDistanceMeters,
